@Bean
public Step nightlyProcessingStep(JobRepository jobRepository, PlatformTransactionManager transactionManager) {
    return new StepBuilder("nightlyStep", jobRepository)
            .<Record, Record>chunk(1000, transactionManager)
            .reader(databaseReader())
            .processor(transformationProcessor())
            .writer(bulkWriter())
            .taskExecutor(taskExecutor()) // Parallelize processing
            .build();
}
